using Microsoft.EntityFrameworkCore;
namespace Society.Api;

public static class GovernanceEndpoints
{
    public static void Map(RouteGroupBuilder t)
    {
        t.MapGet("/positions", async (Guid tenant, AppDb db, Access a) => { await a.Member(tenant); return await db.OfficerPositions.Where(x => x.TenantId == tenant).OrderBy(x => x.Level).ThenBy(x => x.Name).Select(x => new { x.Id, x.Name, x.Level, x.RoleId, x.AllowConcurrent, x.Responsibilities, x.Active,x.Required }).ToListAsync(); });
        t.MapPost("/positions", async (Guid tenant, OfficerPositionRequest r, AppDb db, Access a) => { await a.Require(tenant, "membership.settings"); await ValidateRole(tenant, r.RoleId, db, a); if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 100) throw new DomainException("Name the position"); var p = new OfficerPosition { TenantId = tenant, Name = r.Name.Trim(), Level = r.Level, RoleId = r.RoleId, AllowConcurrent = r.AllowConcurrent, Responsibilities = r.Responsibilities, Active = r.Active,Required=r.Required }; db.OfficerPositions.Add(p); a.Audit(tenant, "position.created", p.Id); await db.SaveChangesAsync(); return Results.Ok(new { p.Id }); });
        t.MapPut("/positions/{id:guid}", async (Guid tenant, Guid id, OfficerPositionRequest r, AppDb db, Access a) => { await a.Require(tenant, "membership.settings"); await ValidateRole(tenant, r.RoleId, db, a); var p = await db.OfficerPositions.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 100) throw new DomainException("Name the position"); if (p.RoleId != r.RoleId && await db.OfficerAppointments.AnyAsync(x => x.TenantId == tenant && x.PositionId == id && x.Status == "Approved" && x.EndsAt > DateTimeOffset.UtcNow)) throw new DomainException("End or revoke current appointments before changing this position's access role"); p.Name = r.Name; p.Level = r.Level; p.RoleId = r.RoleId; p.AllowConcurrent = r.AllowConcurrent; p.Responsibilities = r.Responsibilities; p.Active = r.Active;p.Required=r.Required; a.Audit(tenant, "position.updated", id); await db.SaveChangesAsync(); return Results.NoContent(); });
        t.MapGet("/appointments", async (Guid tenant, Guid? unit, Guid? member, int? page, AppDb db, Access a, MembershipService s) => { await a.Member(tenant); var visible = await s.Directory(tenant); var memberships = visible.Select(x => x.Id); var scope = a.Visible(tenant, "members.read").Select(x => x.Id); var manage = a.Visible(tenant, "governance.manage").Select(x => x.Id); var societyManage = await a.Can(tenant, "governance.manage"); var q = db.OfficerAppointments.Where(x => x.TenantId == tenant && (memberships.Contains(x.MembershipId) || (x.UnitId != null && scope.Contains(x.UnitId.Value)))); if (unit != null) q = q.Where(x => x.UnitId == unit); if (member != null) q = q.Where(x => x.MembershipId == member); var now = DateTimeOffset.UtcNow; return await (from ap in q join p in db.OfficerPositions on ap.PositionId equals p.Id join m in db.Memberships on ap.MembershipId equals m.Id join person in db.Persons on m.PersonId equals person.Id orderby ap.StartsAt descending select new { canManage = ap.UnitId == null ? societyManage : manage.Contains(ap.UnitId.Value), ap.Id, ap.MembershipId, ap.UnitId, ap.PositionId, ap.StartsAt, ap.EndsAt, ap.Status, ap.Method, documentIds = scope.Contains(db.Memberships.Where(m => m.Id == ap.MembershipId).Select(m => m.ChapterId).First()) ? ap.DocumentIds : null, notes = scope.Contains(db.Memberships.Where(m => m.Id == ap.MembershipId).Select(m => m.ChapterId).First()) ? ap.Notes : null, ap.Revision, position = p.Name, person = person.FullName, period = ap.EndsAt <= now ? "Past" : ap.StartsAt > now ? "Incoming" : m.Status!="Active"||m.EndsAt<=now?"Membership inactive":"Current" }).Skip(Math.Clamp((page ?? 1) - 1, 0, 1000000) * 50).Take(50).ToListAsync(); });
        t.MapPost("/appointments", async (Guid tenant, OfficerAppointmentRequest r, AppDb db, Access a) => { await a.Require(tenant, "governance.manage", r.UnitId); await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var member = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.MembershipId && x.Status == "Active") ?? throw new DomainException("Appoint an active society member"); if (await db.Persons.AnyAsync(x => x.Id == member.PersonId && x.UserId == a.UserId)) throw new DomainException("You cannot appoint yourself to a governance position"); if (r.EndsAt <= r.StartsAt) throw new DomainException("Term end must follow its start");if(member.EndsAt!=null&&r.EndsAt>member.EndsAt)throw new DomainException("Officer term cannot extend beyond the membership term");if(member.EffectiveFrom>DateTimeOffset.UtcNow&&r.StartsAt<member.EffectiveFrom)throw new DomainException("Officer term cannot precede the future membership start"); var documents = r.DocumentIds ?? []; if (await db.MemberDocuments.CountAsync(d => d.TenantId == tenant && d.MembershipId == member.Id && documents.Contains(d.Id)) != documents.Distinct().Count()) throw new DomainException("Supporting documents must belong to the appointed member"); if (r.UnitId != null && !await a.InWorkspace(db.Units.Where(x => x.TenantId == tenant), tenant, r.UnitId).AnyAsync(x => x.Id == member.ChapterId)) throw new DomainException("The member's chapter is outside the appointed organization"); var position = await db.OfficerPositions.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.PositionId && x.Active) ?? throw new DomainException("Choose an active officer position"); if(position.Level is "Chapter" or "Region"){if(r.UnitId==null||!await db.Units.AnyAsync(u=>u.TenantId==tenant&&u.Id==r.UnitId&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind==position.Level)))throw new DomainException("Choose an organization matching this position's chapter or region level");}await ValidateRole(tenant, position.RoleId, db, a, r.UnitId); if (!position.AllowConcurrent && await db.OfficerAppointments.AnyAsync(x => x.TenantId == tenant && x.UnitId == r.UnitId && x.PositionId == r.PositionId && x.Status != "Revoked" && x.Status != "Rejected" && x.StartsAt < r.EndsAt && x.EndsAt > r.StartsAt)) throw new DomainException("This position already has an overlapping term"); var appointment = new OfficerAppointment { TenantId = tenant, MembershipId = member.Id, UnitId = r.UnitId, PositionId = position.Id, StartsAt = r.StartsAt.ToUniversalTime(), EndsAt = r.EndsAt.ToUniversalTime(), Method = r.Method, Notes = r.Notes, DocumentIds = documents, AuthorityId = a.UserId }; db.OfficerAppointments.Add(appointment); a.Audit(tenant, "officer.appointment.proposed", appointment.Id); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Ok(new { appointment.Id }); });
        t.MapPost("/appointments/{id:guid}/decision", async (Guid tenant, Guid id, MemberDecisionRequest r, AppDb db, Access a) => { await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var appointment = await db.OfficerAppointments.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); await a.Require(tenant, "governance.manage", appointment.UnitId); if (appointment.Revision != r.Revision) return Results.Conflict(); if (appointment.Status != "Pending") throw new DomainException("Appointment already decided"); if (r.Decision is not ("Approve" or "Reject")) throw new DomainException("Choose approve or reject"); if (r.Decision == "Approve") await Activate(appointment, db, a); else appointment.Status = "Rejected"; appointment.Revision++; a.Audit(tenant, "officer.appointment.decided", id, new { r.Decision }); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.NoContent(); });
        t.MapPost("/appointments/{id:guid}/revoke", async (Guid tenant, Guid id, AppDb db, Access a) => { await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var appointment = await db.OfficerAppointments.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); await a.Require(tenant, "governance.manage", appointment.UnitId); appointment.Status = "Revoked"; appointment.Revision++; if (appointment.AssignmentId is { } aid) { var assignment = await db.Assignments.FindAsync(aid); if (assignment != null) assignment.RevokedAt = DateTimeOffset.UtcNow; } a.Audit(tenant, "officer.appointment.revoked", id); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.NoContent(); });
        t.MapGet("/handovers", async (Guid tenant, int? page, AppDb db, Access a) => { await a.Member(tenant); var units = a.Visible(tenant, "governance.manage").Select(x => x.Id); var society = await a.Can(tenant, "governance.manage"); return await db.LeadershipHandovers.Where(x => x.TenantId == tenant && (society || db.OfficerAppointments.Any(ap => (ap.Id == x.OutgoingId || ap.Id == x.IncomingId) && ((ap.UnitId != null && units.Contains(ap.UnitId.Value)) || db.Memberships.Any(m => m.Id == ap.MembershipId && db.Persons.Any(p => p.Id == m.PersonId && p.UserId == a.UserId)))))).OrderByDescending(x => x.Id).Skip(Math.Clamp((page??1)-1,0,1000000)*100).Take(100).Select(x => new { canReview = db.OfficerAppointments.Any(ap => ap.Id == x.IncomingId && db.Memberships.Any(m => m.Id == ap.MembershipId && db.Persons.Any(p => p.Id == m.PersonId && p.UserId == a.UserId))), canApprove = society || db.OfficerAppointments.Any(ap => ap.Id == x.IncomingId && ap.UnitId != null && units.Contains(ap.UnitId.Value)), x.Id, x.OutgoingId, x.IncomingId, x.Status, x.Notes, x.Revision }).ToListAsync(); });
        t.MapPost("/handovers", async (Guid tenant, HandoverRequest r, AppDb db, Access a) => { var outgoing = await db.OfficerAppointments.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.OutgoingId) ?? throw new AccessDeniedException(); await a.Require(tenant, "governance.manage", outgoing.UnitId); var incoming = await db.OfficerAppointments.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.IncomingId) ?? throw new DomainException("Incoming appointment not found"); if (outgoing.Id == incoming.Id || outgoing.PositionId != incoming.PositionId || outgoing.UnitId != incoming.UnitId || incoming.StartsAt < outgoing.EndsAt || incoming.Status is not ("Pending" or "Approved")) throw new DomainException("Choose a compatible non-overlapping successor term"); var handover = new LeadershipHandover { TenantId = tenant, OutgoingId = outgoing.Id, IncomingId = incoming.Id, Notes = r.Notes }; db.LeadershipHandovers.Add(handover); a.Audit(tenant, "leadership.handover.prepared", handover.Id); await db.SaveChangesAsync(); return Results.Ok(new { handover.Id }); });
        t.MapPost("/handovers/{id:guid}/decision", async (Guid tenant, Guid id, MemberDecisionRequest r, AppDb db, Access a) => { await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var h = await db.LeadershipHandovers.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (h.Revision != r.Revision) return Results.Conflict(); var incoming = await db.OfficerAppointments.SingleAsync(x => x.TenantId == tenant && x.Id == h.IncomingId); if (r.Decision == "Review") { if (h.Status != "Prepared" || !await db.Memberships.AnyAsync(m => m.Id == incoming.MembershipId && db.Persons.Any(p => p.Id == m.PersonId && p.UserId == a.UserId))) throw new AccessDeniedException(); h.Status = "Reviewed"; } else if (r.Decision == "Approve") { await a.Require(tenant, "governance.manage", incoming.UnitId); if (h.Status != "Reviewed") throw new DomainException("Incoming officer must review the handover first"); if (incoming.Status == "Pending") await Activate(incoming, db, a); h.Status = "Approved"; } else throw new DomainException("Invalid handover transition"); h.Revision++; a.Audit(tenant, "leadership.handover.updated", id, new { h.Status }); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.NoContent(); });
        MapCommittees(t);
    }
    static async Task ValidateRole(Guid tenant, Guid? role, AppDb db, Access a, Guid? unit = null) { if (role == null) return; var r = await db.GovernanceRoles.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == role) ?? throw new DomainException("Access role belongs to another society"); foreach (var permission in r.Permissions) await a.Require(tenant, permission, unit); }
    static async Task Activate(OfficerAppointment ap, AppDb db, Access a) { var member = await db.Memberships.SingleAsync(x => x.Id == ap.MembershipId && x.TenantId == ap.TenantId); if (member.Status != "Active") throw new DomainException("Officer must have an active membership"); var person = await db.Persons.SingleAsync(x => x.Id == member.PersonId); if (person.UserId == a.UserId) throw new DomainException("An officer cannot approve their own appointment"); var position = await db.OfficerPositions.SingleAsync(x => x.TenantId == ap.TenantId && x.Id == ap.PositionId); await ValidateRole(ap.TenantId, position.RoleId, db, a, ap.UnitId); if (person.UserId == null && position.RoleId != null) throw new DomainException("The officer must claim their verified login before receiving administrative permissions"); if (position.RoleId is { } role) { var assignment = new Assignment { TenantId = ap.TenantId, UserId = person.UserId!.Value, RoleId = role, UnitId = ap.UnitId, MembershipId = member.Id, StartsAt = ap.StartsAt, EndsAt = ap.EndsAt }; db.Assignments.Add(assignment); ap.AssignmentId = assignment.Id; } ap.Status = "Approved"; }
    static void MapCommittees(RouteGroupBuilder t)
    {
        t.MapGet("/committees", async (Guid tenant, Guid? unit, bool? active,int? page, AppDb db, Access a) => { await a.Member(tenant); var scope = a.Visible(tenant, "units.read").Select(x => x.Id); var manage = a.Visible(tenant, "committees.manage").Select(x => x.Id); var societyManage = await a.Can(tenant, "committees.manage"); var q = db.Committees.Where(x => x.TenantId == tenant && (x.UnitId == null || scope.Contains(x.UnitId.Value))); if (unit != null) q = q.Where(x => x.UnitId == unit); if (active == true) q = q.Where(x => x.Status == "Active" && x.StartsAt <= DateTimeOffset.UtcNow && (x.EndsAt == null || x.EndsAt > DateTimeOffset.UtcNow)); return await q.OrderBy(x => x.Name).ThenBy(x=>x.Id).Skip(Math.Clamp((page??1)-1,0,1000000)*100).Take(100).Select(x => new { canManage = x.UnitId == null ? societyManage : manage.Contains(x.UnitId.Value), x.Id, x.Name, x.Purpose, x.UnitId, x.Status, x.StartsAt, x.EndsAt, x.Revision, members = db.CommitteeMemberships.Count(m => m.TenantId == tenant && m.CommitteeId == x.Id && m.StartsAt <= DateTimeOffset.UtcNow && (m.EndsAt == null || m.EndsAt > DateTimeOffset.UtcNow)) }).ToListAsync(); });
        t.MapPost("/committees", async (Guid tenant, CommitteeRequest r, AppDb db, Access a) => { await a.Require(tenant, "committees.manage", r.UnitId); if (!new[] { "Active", "Inactive", "Closed" }.Contains(r.Status) || string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 160 || r.EndsAt <= r.StartsAt) throw new DomainException("Invalid committee name or dates"); var committee = new Committee { TenantId = tenant, UnitId = r.UnitId, Name = r.Name, Purpose = r.Purpose, Status = r.Status, StartsAt = r.StartsAt.ToUniversalTime(), EndsAt = r.EndsAt?.ToUniversalTime() }; db.Committees.Add(committee); a.Audit(tenant, "committee.created", committee.Id); await db.SaveChangesAsync(); return Results.Ok(new { committee.Id }); });
        t.MapPut("/committees/{id:guid}", async (Guid tenant, Guid id, CommitteeRequest r, AppDb db, Access a) => { var c = await db.Committees.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); await a.Require(tenant, "committees.manage", c.UnitId); if (c.UnitId != r.UnitId) throw new DomainException("Committee ownership is immutable"); if (c.Revision != r.Revision) return Results.Conflict(); if (!new[] { "Active", "Inactive", "Closed" }.Contains(r.Status) || string.IsNullOrWhiteSpace(r.Name) || r.EndsAt <= r.StartsAt) throw new DomainException("Invalid committee details"); c.Name = r.Name; c.Purpose = r.Purpose; c.Status = r.Status; c.StartsAt = r.StartsAt.ToUniversalTime(); c.EndsAt = r.EndsAt?.ToUniversalTime(); c.Revision++; a.Audit(tenant, "committee.updated", id); await db.SaveChangesAsync(); return Results.NoContent(); });
        t.MapGet("/committees/{id:guid}/members", async (Guid tenant, Guid id,int? page, AppDb db, Access a, MembershipService s) => { var c = await db.Committees.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (c.UnitId != null) await a.Require(tenant, "units.read", c.UnitId); else await a.Member(tenant); var visible = (await s.Directory(tenant)).Select(x => x.Id); return await (from cm in db.CommitteeMemberships join m in db.Memberships on cm.MembershipId equals m.Id join p in db.Persons on m.PersonId equals p.Id where cm.TenantId == tenant && cm.CommitteeId == id && visible.Contains(m.Id) orderby cm.StartsAt descending select new { cm.Id, cm.MembershipId, cm.Role, cm.Responsibilities, cm.StartsAt, cm.EndsAt, name = p.FullName }).Skip(Math.Clamp((page??1)-1,0,1000000)*200).Take(200).ToListAsync(); });
        t.MapPost("/committees/{id:guid}/members", async (Guid tenant, Guid id, CommitteeMemberRequest r, AppDb db, Access a) => { var c = await db.Committees.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); await a.Require(tenant, "committees.manage", c.UnitId); if (r.EndsAt <= r.StartsAt || !await db.Memberships.AnyAsync(x => x.TenantId == tenant && x.Id == r.MembershipId && x.Status == "Active")) throw new DomainException("Choose an active society member and valid dates"); if (c.UnitId != null && !await a.InWorkspace(db.Units.Where(x => x.TenantId == tenant), tenant, c.UnitId).AnyAsync(u => db.Memberships.Any(m => m.Id == r.MembershipId && m.ChapterId == u.Id))) throw new DomainException("Member is outside the committee organization"); var cm = new CommitteeMembership { TenantId = tenant, CommitteeId = id, MembershipId = r.MembershipId, Role = r.Role, Responsibilities = r.Responsibilities, StartsAt = r.StartsAt.ToUniversalTime(), EndsAt = r.EndsAt?.ToUniversalTime() }; db.CommitteeMemberships.Add(cm); a.Audit(tenant, "committee.member.added", id); await db.SaveChangesAsync(); return Results.Ok(new { cm.Id }); });
        t.MapDelete("/committees/{id:guid}/members/{membership:guid}", async (Guid tenant, Guid id, Guid membership, AppDb db, Access a) => { var c = await db.Committees.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); await a.Require(tenant, "committees.manage", c.UnitId); var cm = await db.CommitteeMemberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.CommitteeId == id && x.Id == membership) ?? throw new DomainException("Committee membership not found"); cm.EndsAt = DateTimeOffset.UtcNow; a.Audit(tenant, "committee.member.removed", id); await db.SaveChangesAsync(); return Results.NoContent(); });
    }
}
